user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "IS_VERIFICATION_PLAN",
    "definition": "The reasoning expresses an intention to validate or confirm that previously assembled behavior actually works, treating verification as a required step before the task is considered complete.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Agent text stating an intent to test, verify, or confirm correctness of the current configuration or result."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly announces a future verification or validation step rather than only describing completed work.",
      "The stated purpose of that step is to confirm correctness of an already-performed setup, not to perform new construction work."
    ],
    "exclusion_conditions": [
      "The reasoning only reports what has already been done without expressing an intent to check it.",
      "The reasoning plans a construction or configuration step whose only purpose is to create the artifact, with no stated confirmation goal."
    ]
  },
  {
    "name": "SIMULATES_END_USER_WORKFLOW",
    "definition": "The action reproduces the sequence of operations that the requester or an external client would perform against the system, using temporary credentials or scratch locations, in order to validate the assembled system rather than to deliver its final state.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that executes the reproduced end-user operation sequence."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that identifies the reproduced sequence as a simulation of what the user or client would do."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the upcoming action as acting like the requester or external client.",
      "The action performs the multi-step operation sequence matching that client behavior, typically with temporary keys, temporary directories, or other throwaway artifacts.",
      "The purpose of the action is to exercise the system as a consumer would, not to produce the final deliverable configuration."
    ],
    "exclusion_conditions": [
      "The action is an ordinary configuration or installation step that constitutes the deliverable itself.",
      "The action is a single isolated probe of one component rather than the user-visible operation sequence.",
      "The reasoning does not connect the action to consumer-side behavior."
    ]
  },
  {
    "name": "OBSERVATION_CONFIRMS_EXPECTED_OUTCOME",
    "definition": "The observation reports a result that matches the specific outcome the reasoning predicted or required, thereby confirming that the intended behavior holds.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning stating the expected or required outcome before the result is inspected."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result whose content matches that expected outcome."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a concrete expected outcome (a value, response, or state) that the upcoming check should produce.",
      "The observation contains a result corresponding to that expectation, allowing the expectation to be judged satisfied."
    ],
    "exclusion_conditions": [
      "The reasoning states no expected outcome, so the result cannot be judged against an expectation.",
      "The observation reports a different or partial result than the one expected.",
      "The observation is unrelated to the expectation expressed in the reasoning."
    ]
  },
  {
    "name": "DIAGNOSES_OBSERVED_FAILURE",
    "definition": "The reasoning explains the cause of a failure or error reported in an observation, attributing it to a specific identifiable condition rather than merely restating the error message.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that identifies why the reported failure occurred."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting an error, failed step, or non-zero outcome."
      }
    ],
    "assertion_conditions": [
      "The observation reports a concrete failure, error message, or unsuccessful operation.",
      "The reasoning names a specific cause for that failure and links it to evidence visible in the observation or the surrounding execution context.",
      "The explanation distinguishes the actual cause from incidental features of the failure output."
    ],
    "exclusion_conditions": [
      "The observation reports success or an inconclusive empty result rather than a failure.",
      "The reasoning merely repeats the error text without attributing a cause.",
      "The reasoning only states that something went wrong without identifying a condition responsible for it."
    ]
  },
  {
    "name": "RECOGNIZES_INCONCLUSIVE_TOOL_RESULT",
    "definition": "The reasoning determines that an observation, although not flagged as an error, fails to answer the question it was meant to answer because of a tool or method limitation, and selects a different method to obtain the information.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that identifies the inadequacy of the previous result and proposes an alternative method."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose output is empty, truncated, or otherwise uninformative for the intended question."
      }
    ],
    "assertion_conditions": [
      "The observation returned output that does not answer the intended question, without an explicit error being reported.",
      "The reasoning attributes the missing information to a limitation of the tool or command form used.",
      "The reasoning specifies a different command, option, or method intended to produce the missing information."
    ],
    "exclusion_conditions": [
      "The observation answers the question adequately, so no replacement method is needed.",
      "The observation reports an explicit error that is diagnosed as a failure cause rather than a tool limitation.",
      "The reasoning retries the identical method without changing it."
    ]
  },
  {
    "name": "REMEDIAL_ACTION_RESOLVES_DIAGNOSED_CAUSE",
    "definition": "A corrective action is selected specifically to eliminate the cause identified in a diagnosis, and the resulting observation shows that the previously failing operation now succeeds.",
    "parameters": [
      {
        "name": "diagnosis",
        "type": "reasoning",
        "description": "Reasoning that identifies the cause of the earlier failure and the form of correction needed."
      },
      {
        "name": "remedial_action",
        "type": "action",
        "description": "The action that alters the condition identified in the diagnosis."
      },
      {
        "name": "result",
        "type": "observation",
        "description": "The observation reporting the outcome of the corrected attempt."
      }
    ],
    "assertion_conditions": [
      "The diagnosis identifies a specific condition responsible for a prior failure.",
      "The remedial action changes exactly that condition, for example by restoring the required option, environment, or execution identity.",
      "The result shows the previously failing step now completing successfully or the intended state now holding."
    ],
    "exclusion_conditions": [
      "The action repeats the earlier attempt without changing the diagnosed condition.",
      "The diagnosis does not identify a cause, making the action a blind retry.",
      "The result does not demonstrate that the previously failing operation now succeeds.",
      "The action addresses an unrelated part of the system."
    ]
  },
  {
    "name": "RESTORES_PRISTINE_STATE_AFTER_TEST",
    "definition": "Following verification activity, the agent deliberately removes or resets the artifacts created during that activity so the system returns to the pre-verification state a real consumer expects to find.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that enumerates the test artifacts to be removed and the target state to restore."
      },
      {
        "name": "cleanup_actions",
        "type": "action[]",
        "description": "Actions that delete, reset, or purge the artifacts created during verification."
      },
      {
        "name": "state_observation",
        "type": "observation",
        "description": "Observation showing the post-cleanup state of the affected resources."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies artifacts created during verification and states that they must be removed or reset to an initial state.",
      "Each cleanup action deletes, resets, or empties one of those identified artifacts.",
      "The state observation shows the affected resources emptied or matching the intended initial configuration."
    ],
    "exclusion_conditions": [
      "No artifacts were created by the agent's own verification activity, so there is nothing to restore.",
      "The cleanup leaves the identified artifacts in place or the observation shows them still present.",
      "The deletion is part of ordinary construction rather than restoring a state that a later consumer should encounter."
    ]
  },
  {
    "name": "ANTICIPATES_CONSUMER_EXECUTION_CONSTRAINTS",
    "definition": "The reasoning considers how an external actor will execute commands against the resulting system and adjusts the final configuration or state so that those anticipated commands succeed without spurious errors.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that models the external actor's future command sequence and derives a constraint on the final state."
      }
    ],
    "assertion_conditions": [
      "The reasoning describes the specific commands or steps an external actor will later run against the system.",
      "The reasoning predicts how the current state would make those steps fail or misbehave.",
      "The reasoning selects a final state choice intended to make those anticipated steps succeed cleanly."
    ],
    "exclusion_conditions": [
      "The reasoning considers only the agent's own immediate commands and their results.",
      "The reasoning mentions external usage but derives no constraint on the final state.",
      "The reasoning merely restates the task description without reasoning about its execution consequences."
    ]
  },
  {
    "name": "VERIFIES_RUNTIME_SERVICE_STATE",
    "definition": "An action inspects running processes, listening sockets, or configuration-test output, and the observation confirms that the intended services are active and bound to the intended endpoints.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that inspects runtime state or validates configuration syntax."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result listing processes, listening addresses, or configuration-test verdicts."
      }
    ],
    "assertion_conditions": [
      "The action queries runtime or validity state of the deployed services rather than their source configuration alone.",
      "The observation reports the services present and active, or the configuration reported as valid, with the expected endpoints or addresses visible."
    ],
    "exclusion_conditions": [
      "The action modifies configuration instead of inspecting runtime state.",
      "The observation shows the service absent, not listening on the intended endpoint, or the configuration reported as invalid.",
      "The observation concerns an unrelated resource rather than the deployed services."
    ]
  },
  {
    "name": "ADDS_AVAILABILITY_SAFEGUARD",
    "definition": "The agent adds a self-healing or re-start mechanism that restores service availability after an unforeseen interruption, going beyond what the immediate task requires in order to make the configuration robust across restarts.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "Reasoning that motivates the extra recovery mechanism as protection against future restarts or interruptions."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that creates or installs the idempotent recovery mechanism."
      }
    ],
    "assertion_conditions": [
      "The reasoning frames the addition as protection against a future interruption or restart rather than as a step needed for the current request.",
      "The action creates or installs a mechanism that checks service presence and restores it when absent, and is safe to invoke repeatedly."
    ],
    "exclusion_conditions": [
      "The action is ordinary service startup needed for the current request to work at all.",
      "The mechanism cannot restore a stopped service or would fail the calling shell on error.",
      "No reasoning connects the mechanism to future availability concerns."
    ]
  }
]

Existing registry:
[
  {
    "name": "IS_PLAN",
    "definition": "The reasoning explicitly expresses at least one intended future action or a sequence of intended future actions that the agent commits to performing.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intended future action or sequence of actions."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies at least one intended future action.",
      "The intended action is presented as something the agent will do next, rather than as a mere possibility or a restatement of the task."
    ],
    "exclusion_conditions": [
      "The reasoning only reports actions already completed.",
      "The reasoning only restates task requirements without committing to a future action."
    ]
  },
  {
    "name": "SPECIFIES_CORRECTIVE_CONTENT_WITH_JUSTIFICATION",
    "definition": "The reasoning supplies concrete content intended to correct, complete, or otherwise modify an artifact and justifies why that content satisfies the target requirement, optionally by evaluating and rejecting an alternative that would fail.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that states the concrete replacement or completion content and the justification for its correctness."
      }
    ],
    "assertion_conditions": [
      "The reasoning states concrete content to be applied to the artifact, such as specific steps, replacement text, or a proof script, not merely the intention to change it.",
      "The reasoning explains why the stated content achieves the goal, using the semantics of the relevant domain entities.",
      "If alternative candidates are considered, at least one is rejected for an identified reason."
    ],
    "exclusion_conditions": [
      "The reasoning only describes the defect or goal without supplying concrete content to apply.",
      "The reasoning only lists generic strategies without indicating which one will be used or why it works."
    ]
  },
  {
    "name": "GROUNDS_CONCLUSION_IN_OBSERVATION",
    "definition": "The reasoning draws a conclusion using identifiable content of the observation as supporting evidence for that conclusion.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning expressing the evidence-based conclusion."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation supplying the evidence used for that conclusion."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a conclusion that goes beyond restating the observation, such as a judgment about correctness, availability, or completion.",
      "Identifiable content of the observation, such as values, listed artifacts, returned text, or computed output, is used as support for that conclusion."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats or summarizes the observation without drawing a conclusion from it.",
      "The observation is unrelated to the conclusion or contains nothing that supports it."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE_AND_PRESCRIBES_CORRECTION",
    "definition": "An observation reports a failed outcome; the reasoning identifies a specific cause for the failure that links it to the semantics of the executed operation, and prescribes a corrective action that differs from the failed one in the diagnosed respect.",
    "parameters": [
      {
        "name": "failure_observation",
        "type": "observation",
        "description": "The observation reporting the error or unsuccessful outcome."
      },
      {
        "name": "diagnosis_reasoning",
        "type": "reasoning",
        "description": "The reasoning explaining the cause of the failure and specifying the corrected approach."
      },
      {
        "name": "corrective_action",
        "type": "action",
        "description": "The action that applies the corrected approach prescribed by the diagnosis."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error or otherwise unsuccessful result.",
      "The reasoning states a specific cause for the failure rather than merely noting that it failed.",
      "The reasoning specifies how the operation must be changed in light of that cause.",
      "The corrective action implements that change and is therefore distinguishable from the failed action."
    ],
    "exclusion_conditions": [
      "The reasoning retries the same operation without identifying a cause or changing the approach.",
      "The reasoning speculates about causes unrelated to the reported error.",
      "The corrective action does not reflect the stated diagnosis."
    ]
  },
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action queries the environment to resolve a specific uncertainty or unverified prerequisite identified in reasoning, and the resulting observation provides evidence that settles or materially informs it before dependent work proceeds.",
    "parameters": [
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the uncertainty or prerequisite that must be settled."
      },
      {
        "name": "probe_action",
        "type": "action",
        "description": "The action performing the targeted query about that uncertainty."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting the result relevant to the uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific open question or prerequisite condition whose value is not yet known.",
      "The probe action is directed at obtaining exactly that information from the environment.",
      "The observation returns information that resolves or materially informs the identified question."
    ],
    "exclusion_conditions": [
      "No identifiable uncertainty or prerequisite motivates the action.",
      "The action is unrelated to the stated question, or the observation does not address it.",
      "The probe merely repeats information already established earlier in the trajectory."
    ]
  },
  {
    "name": "VERIFIES_REQUIREMENT_SATISFACTION",
    "definition": "After an outcome has been produced, a separate verification action inspects the produced artifact or result, its observation demonstrates the required property directly rather than only the absence of errors, and the reasoning concludes from it that the requirement is satisfied.",
    "parameters": [
      {
        "name": "verification_action",
        "type": "action",
        "description": "The action that inspects or exercises the already produced outcome."
      },
      {
        "name": "verification_observation",
        "type": "observation",
        "description": "The observation containing content that demonstrates the required property."
      },
      {
        "name": "concluding_reasoning",
        "type": "reasoning",
        "description": "The reasoning concluding that the requirement is met on the basis of that observation."
      }
    ],
    "assertion_conditions": [
      "The verification action is distinct from the action that produced the outcome and targets the produced artifact or result.",
      "The observation exposes content showing the required property actually holds, for example the resulting object is present and carries the expected content.",
      "The reasoning explicitly concludes that the requirement is satisfied, citing that observation."
    ],
    "exclusion_conditions": [
      "The action is the one that produced the outcome rather than an independent check of it.",
      "The observation only indicates that no error occurred, without demonstrating the required property.",
      "No conclusion is drawn from the observation, or the conclusion is not tied to it."
    ]
  },
  {
    "name": "ENUMERATES_REQUIRED_COMPONENTS",
    "definition": "The reasoning decomposes a stated goal into multiple distinct components, accounts, permissions, or artifacts that must exist for the goal to be satisfiable, turning the goal description into identifiable configuration obligations.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text listing the components or artifacts that must exist for the stated goal to be satisfiable."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies multiple distinct elements that must exist or be configured, such as an account, a repository, a deployment mechanism, or a serving process.",
      "Each identified element is justified by the goal's expected usage or by an explicit dependency of the goal rather than being listed arbitrarily.",
      "The enumeration includes required state, artifacts, or configuration obligations beyond merely ordering actions to perform."
    ],
    "exclusion_conditions": [
      "The reasoning only restates the goal without identifying required elements.",
      "The reasoning only gives an ordered procedure or action plan without identifying what must exist.",
      "The reasoning proposes only a single required element or an incidental detail."
    ]
  },
  {
    "name": "IMPLEMENTS_PLANNED_STEP",
    "definition": "The action carries out a concrete operation or creates/configures an artifact that the reasoning explicitly identified as an intended step, so the action is the observable execution of a previously stated intention.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The recorded tool invocation that performs the intended step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning that explicitly states the intended step which the action executes."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly names the operation or artifact that the action then operates on before that action occurs.",
      "The action's content matches the intended step in purpose and target, not merely in topic.",
      "The action executes that intended step rather than an unrelated exploration."
    ],
    "exclusion_conditions": [
      "The action explores the environment without a corresponding previously stated intention.",
      "The reasoning mentions the operation or artifact only after the action's result is known.",
      "The action's target or purpose differs from the stated intention."
    ]
  },
  {
    "name": "ANTICIPATES_PROCEDURAL_PITFALL",
    "definition": "The reasoning predicts a specific failure mode or unusable outcome that would arise from a default or naive procedure and states a preventive or corrective configuration measure derived from that prediction.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that predicts the failure mode and states the preventive or corrective measure."
      }
    ],
    "assertion_conditions": [
      "The reasoning describes a concrete way the default or planned procedure could fail or produce an unusable result.",
      "The reasoning links that predicted failure to a preventive or corrective measure that changes the procedure or configuration.",
      "The predicted failure is prospective rather than an already observed error."
    ],
    "exclusion_conditions": [
      "The reasoning observes a failure that has already occurred rather than predicting one.",
      "The reasoning lists general best practices without linking them to an identified failure mode.",
      "The reasoning predicts a failure but does not state any measure addressing it."
    ]
  },
  {
    "name": "VALIDATES_BEFORE_ACTIVATION",
    "definition": "An action applies a configuration to a service or running system only after an explicit validity check of that configuration within the same invocation, and the observation reports both the successful validation and the activated or applied service.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The tool invocation that performs the configuration validity check and then applies or activates the configuration."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result reporting the validation outcome and the activation or application state of the service."
      }
    ],
    "assertion_conditions": [
      "The action includes an explicit validation of the configuration before starting, reloading, or otherwise applying it.",
      "Activation or application is conditioned on that validation succeeding within the same invocation.",
      "The observation reports the validation as successful and shows the service running or the configuration applied."
    ],
    "exclusion_conditions": [
      "The service is started without any preceding configuration validation.",
      "Validation is performed but activation or application does not follow.",
      "The observation shows a validation failure or no evidence that the service is active or the configuration applied.",
      "Validation and activation occur in separate invocations, or the validation concerns an unrelated configuration."
    ]
  }
]

